'use strict';
let circleAim=null;
const activeCircle=()=>!editing&&state?.status==='running';
function rawBoardPoint(e){const p=board.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(board.getScreenCTM().inverse());return {x:(q.x-OR)/S,y:(q.y-OR)/S};}
function startProjection(p){const a=track.start[0],b=track.start[1],dx=b.x-a.x,dy=b.y-a.y;const u=((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy);return {u,point:{x:a.x+u*dx,y:a.y+u*dy},distance:Math.abs((p.x-a.x)*dy-(p.y-a.y)*dx)/Math.hypot(dx,dy)};}
function circleSetAim(ax,ay){if(!activeCircle())return;const d=Math.hypot(ax,ay);circleAim=d>1?{ax:ax/d,ay:ay/d}:{ax,ay};drawPreview();const marker=$('aimMarker');marker.setAttribute('cx',100+circleAim.ax*76);marker.setAttribute('cy',100+circleAim.ay*76);const o=R.evaluate(track,state,circleAim.ax,circleAim.ay);$('aimValue').textContent=`速度调整 (${circleAim.ax.toFixed(2)}, ${circleAim.ay.toFixed(2)}) · 长度 ${Math.hypot(circleAim.ax,circleAim.ay).toFixed(2)}`+($('warnings').checked&&o.status==='crashed'?' · 会撞墙':'');}
function circlePadPoint(e){const svg=$('aimPad'),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(svg.getScreenCTM().inverse());return {ax:(q.x-100)/76,ay:(q.y-100)/76};}
function circleCommit(){if(!activeCircle()||!circleAim)return;const a=circleAim;circleAim=null;move(a.ax,a.ay);}
const oldBoardRender=renderBoard;
renderBoard=function(){if(editing){oldBoardRender();board.querySelectorAll('rect[fill="url(#grid)"]').forEach(n=>n.remove());return;}
board.replaceChildren(el('rect',{width:1200,height:840,fill:'#fcfdff'}));drawTrack(track);
board.append(line({x:2,y:31},{x:3,y:31},{stroke:'#697f98','stroke-width':2}),textAt({x:2,y:30.6},'1 单位',{'font-size':13}));
if(!state){board.append(line(...track.start,{stroke:'#15886e','stroke-width':18,opacity:.14}),textAt({x:track.path[0].x,y:track.path[0].y-1.1},'点击线上任意位置发车',{'text-anchor':'middle',fill:'#15886e','font-size':15}));return;}
const trail=history.map(s=>s.status==='running'?s.position:s.impact);if(trail.length>1)board.append(el('polyline',{points:pointStr(trail),fill:'none',stroke:'#df5b27','stroke-width':3,'stroke-linejoin':'round'}));trail.slice(0,-1).forEach((p,i)=>{const q=xy(p);board.append(el('circle',{cx:q.x,cy:q.y,r:3,fill:'#df5b27'}),textAt({x:p.x+.2,y:p.y-.2},String(i),{fill:'#a76c52','font-size':11}));});
if(state.status==='running'){const c={x:state.position.x+state.velocity.x,y:state.position.y+state.velocity.y},q=xy(c);board.append(line(state.position,c,{stroke:'#8497b0','stroke-width':2,'stroke-dasharray':'7 6'}),el('circle',{cx:q.x,cy:q.y,r:S,fill:'#3165dd15',stroke:'#3165dd','stroke-width':2}),el('circle',{cx:q.x,cy:q.y,r:3,fill:'#3165dd'}));}
const car=state.status==='running'?state.position:state.impact,q=xy(car);board.append(el('circle',{cx:q.x,cy:q.y,r:11,fill:'#df5b2725','pointer-events':'none'}),el('circle',{cx:q.x,cy:q.y,r:6,fill:state.status==='crashed'?'#ba3b35':'#df5b27',stroke:'#fff','stroke-width':2,'pointer-events':'none'}));if(state.status==='crashed')board.append(el('path',{d:`M${q.x-10} ${q.y-10}l20 20m0 -20l-20 20`,stroke:'#ba3b35','stroke-width':3}));board.append(el('g',{id:'previewLayer','pointer-events':'none'}));drawPreview();};
drawPreview=function(){const g=$('previewLayer');if(!g)return;g.replaceChildren();if(!activeCircle()||!circleAim)return;const o=R.evaluate(track,state,circleAim.ax,circleAim.ay),danger=$('warnings').checked&&o.status==='crashed',q=xy(o.position);g.append(line(state.position,o.position,{stroke:danger?'#c7524a':'#3165dd','stroke-width':3,'stroke-dasharray':'5 4'}),el('circle',{cx:q.x,cy:q.y,r:5,fill:danger?'#c7524a':'#3165dd'}));if(danger){const c=xy(o.impact);g.append(el('circle',{cx:c.x,cy:c.y,r:9,fill:'#c7524a25',stroke:'#c7524a'}));}};
const previousCircleRender=render;render=function(){previousCircleRender();$('modeTag').textContent=editing?'自由画线':practice?'V2 · 连续练习':'V2 · 连续驾驶';$('moveCaption').textContent=activeCircle()?'调整速度，长度 ≤ 1':'等待发车';$('velocity').textContent=state?`横向 ${state.velocity.x.toFixed(2)} · 纵向 ${state.velocity.y.toFixed(2)}`:'尚未移动';$('keepSpeed').disabled=!activeCircle();$('aimConfirm').disabled=!activeCircle();$('aimPad').classList.toggle('inactive',!activeCircle());
if(!editing&&!state){$('statusTitle').textContent='选择你的起点';$('statusText').textContent='点击绿色起跑线上的任意位置，位置不再吸附到格点。';}else if(activeCircle()){$('statusText').textContent='圆内自由选点；圈外点击自动投影到朝向鼠标的圆周交点。圆心表示保持速度。';}if(editing){$('editorMessage').textContent=$('editorMessage').textContent.replaceAll('格','单位');$('widthValue').textContent=$('width').value+' 单位';}
if(!circleAim&&activeCircle())circleSetAim(0,0);else if(!activeCircle()){$('aimValue').textContent='半径 1 · 圆内任意位置';}}
function circleBoardAim(p){circleSetAim(p.x-(state.position.x+state.velocity.x),p.y-(state.position.y+state.velocity.y));}
board.addEventListener('pointermove',e=>{if(editing)return;const p=rawBoardPoint(e);if(!state){const s=startProjection(p);board.style.cursor=s.distance<.6&&s.u>0&&s.u<1?'pointer':'default';return;}if(!activeCircle())return;board.style.cursor='crosshair';circleBoardAim(p);});
board.addEventListener('click',e=>{if(editing)return;const p=rawBoardPoint(e);if(!state){const s=startProjection(p);if(s.distance<.6&&s.u>.001&&s.u<.999){circleAim=null;chooseStart(s.point);}return;}if(!activeCircle())return;circleBoardAim(p);circleCommit();});
$('aimPad').addEventListener('pointermove',e=>{if(!activeCircle())return;const a=circlePadPoint(e);circleSetAim(a.ax,a.ay);});$('aimPad').addEventListener('click',e=>{if(!activeCircle())return;const a=circlePadPoint(e);circleSetAim(a.ax,a.ay);circleCommit();});$('aimConfirm').onclick=circleCommit;$('keepSpeed').onclick=()=>{if(activeCircle()){circleSetAim(0,0);circleCommit();}};
const previousCircleMove=move;move=function(ax,ay){circleAim=null;previousCircleMove(ax,ay);};const previousCircleReset=reset;reset=function(){circleAim=null;previousCircleReset();};$('restart').onclick=reset;
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'choose_continuous_start',description:'Choose any position along the start line, as a fraction strictly between 0 and 1. Restarts the human race.',inputSchema:{type:'object',properties:{fraction:{type:'number',exclusiveMinimum:0,exclusiveMaximum:1}},required:['fraction'],additionalProperties:false},execute:input=>{if(editing||!Number.isFinite(input?.fraction)||input.fraction<=0||input.fraction>=1)throw Error('Invalid start fraction');const u=input.fraction;chooseStart({x:track.start[0].x*(1-u)+track.start[1].x*u,y:track.start[0].y*(1-u)+track.start[1].y*u});return {position:state.position,velocity:state.velocity};},annotations:{readOnlyHint:false,untrustedContentHint:false}})).catch(()=>{});}catch{}}

